INSERT INTO practices (type, area, topic, level, title, summary, est_minutes, content_json, sort_order) VALUES
  ('UNIT', 'SAFETY', '안전·자기 보호', 1, '안전·자기 보호', '랜선 연애와 그루밍, 낯선 사람, 또래의 비행 권유에서 멈추는 연습이에요.', 10, '{"questions":[{"id":"q1","text":"처음 보는 사람이 “둘만의 비밀이야”라며 내 사진을 보내 달래요.","options":[{"id":"a","label":"사진을 보내 준다"},{"id":"b","label":"보내지 않고 대화를 멈춘다"},{"id":"c","label":"잘 모르겠어요"}],"compare":{"title":"최고의 선택","best":"b","reason":"비밀이라며 사진을 달라는 건 경계를 넘는 신호일 수 있어요. 멈추는 건 나를 지키는 선택이에요. 어른에게 보여 주면 더 든든해요."}},{"id":"q2","text":"게임에서 만난 사람이 “선물 줄게, 혼자 나와”라고 해요.","options":[{"id":"a","label":"혼자 만나러 간다"},{"id":"b","label":"가지 않고 어른에게 이야기한다"},{"id":"c","label":"잘 모르겠어요"}],"compare":{"title":"최고의 선택","best":"b","reason":"혼자 만나자는 부탁은 위험할 수 있어요. 가지 않고 어른에게 알리면 함께 안전하게 정할 수 있어요."}},{"id":"q3","text":"친구들이 “같이 가게에서 몰래 가져오자”라고 해요.","options":[{"id":"a","label":"같이 간다"},{"id":"b","label":"하고 싶지 않다고 말하고 자리를 피한다"},{"id":"c","label":"잘 모르겠어요"}],"compare":{"title":"최고의 선택","best":"b","reason":"친구와의 관계가 걱정돼도 하고 싶지 않다고 말하는 건 괜찮아요. 자리를 피하는 것도 좋은 방법이에요."}},{"id":"q4","text":"온라인에서 만난 사람이 “내가 도와줄게, 사는 곳 알려 줘”라고 해요.","options":[{"id":"a","label":"사는 곳을 알려 준다"},{"id":"b","label":"알려 주지 않고 믿을 수 있는 어른에게 이야기한다"},{"id":"c","label":"잘 모르겠어요"}],"compare":{"title":"최고의 선택","best":"b","reason":"모르는 사람에게 사는 곳을 알려 주지 않아도 괜찮아요. 도움이 필요하면 믿을 수 있는 어른과 함께 방법을 정해요."}},{"id":"q5","text":"불편한 부탁을 받으면 “싫어”라고 말할 수 있어요.","options":[{"id":"a","label":"전혀 아니에요"},{"id":"b","label":"아니에요"},{"id":"c","label":"보통이에요"},{"id":"d","label":"그래요"},{"id":"e","label":"매우 그래요"}],"compare":{"title":"이렇게 생각해 볼 수 있어요","best":null,"reason":"“싫어”가 어렵다면 “생각해 볼게”나 자리를 피하는 말로 시작해도 괜찮아요."}},{"id":"q6","text":"불편한 일이 생기면 믿을 수 있는 어른에게 말할 수 있어요.","options":[{"id":"a","label":"전혀 아니에요"},{"id":"b","label":"아니에요"},{"id":"c","label":"보통이에요"},{"id":"d","label":"그래요"},{"id":"e","label":"매우 그래요"}],"compare":{"title":"이렇게 생각해 볼 수 있어요","best":null,"reason":"말하기 어려운 날도 있어요. 어른 목록을 미리 정해 두면 도움이 돼요."}},{"id":"q7","text":"불편하다는 마음이 들면 그 마음을 믿어도 돼요.","options":[{"id":"a","label":"전혀 아니에요"},{"id":"b","label":"아니에요"},{"id":"c","label":"보통이에요"},{"id":"d","label":"그래요"},{"id":"e","label":"매우 그래요"}],"compare":{"title":"이렇게 생각해 볼 수 있어요","best":null,"reason":"불편한 마음은 나를 지키는 신호가 될 수 있어요. 확신이 없어도 잠깐 멈춰 봐도 괜찮아요."}},{"id":"q8","text":"도움을 청하는 건 용기 있는 일이라고 생각해요.","options":[{"id":"a","label":"전혀 아니에요"},{"id":"b","label":"아니에요"},{"id":"c","label":"보통이에요"},{"id":"d","label":"그래요"},{"id":"e","label":"매우 그래요"}],"compare":{"title":"이렇게 생각해 볼 수 있어요","best":null,"reason":"도움을 청하는 건 약한 게 아니에요. 아직 그렇게 느껴지지 않아도 괜찮아요."}}],"cards":[{"title":"“비밀이야”라는 말이 나오면","l1":"온라인에서 처음 만난 사람이 “비밀로 하자”고 하면 한 번 멈춰 봐요.","l2":"좋은 사람이라면 비밀을 강요하지 않아요."},{"title":"나에게 잘해 주는 것 같아도","l1":"선물, 칭찬, 특별한 관심이 갑자기 늘면 이유를 살펴봐요.","l2":"불편하다는 마음이 들면 그 마음이 신호예요."},{"title":"단톡방에서 온 부탁","l1":"어려운 부탁을 받았을 때 어떻게 말할지 미리 생각해 봐요.","l2":"정답은 하나가 아니에요. 내가 편한 방법을 찾는 게 목적이에요."},{"title":"벤치에 혼자 앉은 친구","l1":"표정과 몸짓에서 보이는 것부터 말해 봐요.","l2":"마음은 하나로 정해지지 않아요. 짐작은 짐작으로 두어도 괜찮아요."},{"title":"멈추고, 말 꺼내기","l1":"멈추는 것도 용기예요. 믿을 수 있는 어른에게 첫 문장을 꺼내 봐요.","l2":"첫 문장은 짧아도 충분해요."}]}', 1),
  ('SCENARIO', 'HELP', '시나리오 연습', 1, '온라인에서 받은 비밀 부탁', '정해진 답 없이 상황을 고르고, 내가 편한 말로 대답해 보는 연습이에요.', 10, '{"scene":"휴대폰 대화창에 비밀 이야기와 사진을 보내 달라는 메시지가 와 있어요.","situation":"온라인 게임에서 알게 된 사람이 \\"너 사진 한 장만 보내 줘. 다른 사람한테는 비밀이야.\\"라고 해요.","choices":[{"id":"c1","text":"왜 비밀이어야 하는지 이유를 물어보고 조금 더 이야기해 본다.","follow":"궁금한 마음이 드는 건 자연스러워요. 다만 이유를 듣다 보면 거절하기가 더 어려워질 수 있어요. 어떤 대답을 듣든, 사진은 보내지 않아도 돼요.","hear":"상대에게는 설득할 틈이 있다는 신호로 들릴 수 있어요."},{"id":"c2","text":"지금은 보내지 않겠다고 말하고 대화를 멈춘다.","follow":"분명하게 멈추는 건 나를 지키는 방법이에요. 상대가 계속 조르거나 화를 낸다면, 그 자체가 조심해야 할 신호예요.","hear":"상대에게는 분명한 거절로 들려요."},{"id":"c3","text":"믿을 수 있는 어른에게 대화를 보여 주고 이야기한다.","follow":"혼자 판단하지 않아도 돼요. 대화를 지우지 말고 보여 주면, 무엇을 남겨 두고 어떻게 막을지 함께 정할 수 있어요.","hear":"걱정이 되어서 도움을 청하는 것으로 들려요. 상대방은 숨기려던 일이 드러나 당황할 수도 있어요."}],"remember":["불편한 마음이 들었다면, 그 느낌은 틀리지 않았어요.","개인 사진을 달라는 부탁과 비밀로 하자는 요구는 살펴봐야 할 경계 신호일 수 있어요.","언제든 대화를 멈추고, 믿을 수 있는 사람에게 도움을 구할 수 있어요."],"feelings":[{"id":"f1","label":"불편했어요"},{"id":"f2","label":"헷갈렸어요"},{"id":"f3","label":"괜찮았어요"},{"id":"f4","label":"누군가에게 말하고 싶어졌어요"}]}', 1),
  ('EMOTION', 'EMOTION', '감정 읽기', 1, '혼자 떨어져 앉은 친구', '짧은 장면을 보고 뚜렷한 단서로 마음을 고르는 연습이에요.', 10, '{"scene":"친구들과 대화가 끝난 뒤, 한 친구가 조금 떨어진 벤치에 혼자 앉아 아래를 보고 있어요.","situation":"점심시간에 함께 이야기하던 친구가 대화가 끝나자 혼자 떨어져 앉았어요.","clues":[{"id":"k1","label":"표정 · 시선을 아래로 향해요"},{"id":"k2","label":"목소리 · 말수가 줄었어요"},{"id":"k3","label":"몸짓 · 어깨가 처져 있어요"},{"id":"k4","label":"하는 말 · “나 괜찮아”라고 짧게 말했어요"},{"id":"k5","label":"앞뒤 상황 · 대화가 끝나자 혼자 떨어져 앉았어요"}],"feelings":[{"id":"f1","label":"서운함"},{"id":"f2","label":"걱정"},{"id":"f3","label":"당황"},{"id":"f4","label":"외로움"},{"id":"f5","label":"잘 모르겠어요","exclusive":true}],"keyClue":"시선이 아래로 향하고, 혼자 떨어져 앉은 모습이에요. 같은 장면에서도 사람마다 다르게 느껴요. 정답이 하나는 아니에요.","askLine":"괜찮아? 이야기하고 싶으면 언제든 들을게."}', 1);
